// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List your API tokens (metadata only)
	// (GET /api-tokens)
	ListApiTokens(w http.ResponseWriter, r *http.Request)
	// Create an API token (the secret is returned only once)
	// (POST /api-tokens)
	CreateApiToken(w http.ResponseWriter, r *http.Request)
	// Revoke an API token
	// (DELETE /api-tokens/{id})
	DeleteApiToken(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List articles (paginated, newest first)
	// (GET /articles)
	ListArticles(w http.ResponseWriter, r *http.Request, params ListArticlesParams)
	// Get an article
	// (GET /articles/{id})
	GetArticle(w http.ResponseWriter, r *http.Request, id int64)
	// Publish a draft article
	// (POST /articles/{id}/publish)
	PublishArticle(w http.ResponseWriter, r *http.Request, id int64)
	// Rate an article (copywriter 👍/👎)
	// (POST /articles/{id}/rating)
	RateArticle(w http.ResponseWriter, r *http.Request, id int64)
	// Authenticate and receive a JWT
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Everything the booking form needs — the hours on offer and the practice areas to choose from
	// (GET /client/booking-options)
	GetClientBookingOptions(w http.ResponseWriter, r *http.Request)
	// The caller's own record — their contact details, whether reminders can reach them, and their consultations
	// (GET /client/me)
	GetClientProfile(w http.ResponseWriter, r *http.Request)
	// A client's own request — their details plus optionally the hour they picked; creates the client if the CRM has never seen them
	// (POST /client/requests)
	SubmitClientRequest(w http.ResponseWriter, r *http.Request)
	// Clients with their derived funnel segment and tags, filtered/paginated — no date range, this is a snapshot of all-time activity, not a period aggregate
	// (GET /clients)
	ListClientSegments(w http.ResponseWriter, r *http.Request, params ListClientSegmentsParams)
	// The curated manual-tag vocabulary — AddClientTag only accepts a tag already listed here
	// (GET /clients/tag-defs)
	ListClientTagDefs(w http.ResponseWriter, r *http.Request)
	// Add a new entry to the tag vocabulary
	// (POST /clients/tag-defs)
	CreateClientTagDef(w http.ResponseWriter, r *http.Request)
	// Remove a tag definition — every client carrying it loses the tag too (idempotent, removing an already-gone label is not an error)
	// (DELETE /clients/tag-defs/{label})
	DeleteClientTagDef(w http.ResponseWriter, r *http.Request, label string)
	// Rename a tag definition and/or move it to another category — omitted fields are left as-is; a rename applies to every client carrying the old label in the same operation
	// (PATCH /clients/tag-defs/{label})
	UpdateClientTagDef(w http.ResponseWriter, r *http.Request, label string)
	// Delete a client record — refused (409) if it has any leads, consultations, or cases, so real business history can't be destroyed by accident
	// (DELETE /clients/{id})
	DeleteClient(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// One client's full card — leads, consultations, cases, manual notes, money actually collected
	// (GET /clients/{id})
	GetClientDetail(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Edit a client's own name/phone from the client card
	// (PATCH /clients/{id})
	UpdateClient(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Add a manual call/contact log entry to a client's card — free text staff types in after a call, there's no phone system integration
	// (POST /clients/{id}/notes)
	AddClientNote(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Pin a client's segment by hand, or pass null to clear the override and fall back to the calculated value
	// (PATCH /clients/{id}/segment)
	SetClientSegmentOverride(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Attach a tag to a client — tag must be one of GET /clients/tag-defs' labels; idempotent, adding a tag already present is not an error
	// (POST /clients/{id}/tags)
	AddClientTag(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Detach a staff-added tag from a client — idempotent, removing a tag that isn't present is not an error
	// (DELETE /clients/{id}/tags/{tag})
	RemoveClientTag(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, tag string)
	// Crawl the sites listed in a sheet and scrape their email addresses
	// (POST /emailscrape)
	ScrapeEmails(w http.ResponseWriter, r *http.Request)
	// Get the progress and state of a scrape job
	// (GET /emailscrape/jobs/{id})
	GetScrapeJob(w http.ResponseWriter, r *http.Request, id string)
	// Request cancellation of a running scrape job
	// (POST /emailscrape/jobs/{id}/cancel)
	CancelScrapeJob(w http.ResponseWriter, r *http.Request, id string)
	// Advocate payout rates — 0 means no automatic payout is generated for that advocate
	// (GET /finance/advocate-rates)
	ListAdvocateRates(w http.ResponseWriter, r *http.Request)
	// Set an advocate's share of what they collect; the generated payout is always a draft to confirm, never posted automatically
	// (PATCH /finance/advocate-rates/{id})
	SetAdvocateRate(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// The closed expense-category vocabulary — free text would drift into three spellings of one line in the P&L
	// (GET /finance/categories)
	ListExpenseCategories(w http.ResponseWriter, r *http.Request, params ListExpenseCategoriesParams)
	// Add a category to the vocabulary
	// (POST /finance/categories)
	CreateExpenseCategory(w http.ResponseWriter, r *http.Request)
	// Rename a category, regroup it, or retire it — the code stays, so history keeps pointing at it
	// (PATCH /finance/categories/{code})
	UpdateExpenseCategory(w http.ResponseWriter, r *http.Request, code string)
	// Expense ledger, newest first — includes drafts, which are excluded from every P&L number until confirmed
	// (GET /finance/expenses)
	ListExpenses(w http.ResponseWriter, r *http.Request, params ListExpensesParams)
	// Record a spend by hand — always posted, there is nothing to confirm about a payment a person already made
	// (POST /finance/expenses)
	CreateExpense(w http.ResponseWriter, r *http.Request)
	// Delete an expense
	// (DELETE /finance/expenses/{id})
	DeleteExpense(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Correct an expense — keeps its draft/posted status, so fixing a generated draft's amount does not post it
	// (PATCH /finance/expenses/{id})
	UpdateExpense(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Accept a generated draft into the ledger — this is the moment it starts counting in the P&L
	// (POST /finance/expenses/{id}/confirm)
	ConfirmExpense(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Money the P&L cannot account for because of how a record was left — the to-do list behind the numbers
	// (GET /finance/gaps)
	GetFinanceGaps(w http.ResponseWriter, r *http.Request, params GetFinanceGapsParams)
	// Materialize the recurring templates and advocate payouts due in a month — idempotent, a repeat run inserts nothing
	// (POST /finance/generate)
	RunAutoExpenses(w http.ResponseWriter, r *http.Request)
	// Money in that never passed through a consultation or a case — refunds, company top-ups, one-offs
	// (GET /finance/income)
	ListOtherIncome(w http.ResponseWriter, r *http.Request, params ListOtherIncomeParams)
	// Record income outside the CRM's own consultation/case flow
	// (POST /finance/income)
	CreateOtherIncome(w http.ResponseWriter, r *http.Request)
	// Delete an other-income entry
	// (DELETE /finance/income/{id})
	DeleteOtherIncome(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// The months the data actually spans — what the period picker offers, so it never proposes an empty window
	// (GET /finance/period)
	GetFinancePeriod(w http.ResponseWriter, r *http.Request)
	// P&L by month — income read from consultations/case payments (never re-entered by hand), expenses summed per category, plus running balance and acquisition metrics
	// (GET /finance/report)
	GetFinanceReport(w http.ResponseWriter, r *http.Request, params GetFinanceReportParams)
	// Recurring expense templates — the monthly charges the generator materializes (hosting, telephony, retainers)
	// (GET /finance/rules)
	ListExpenseRules(w http.ResponseWriter, r *http.Request, params ListExpenseRulesParams)
	// Add a recurring expense template
	// (POST /finance/rules)
	CreateExpenseRule(w http.ResponseWriter, r *http.Request)
	// Delete a recurring template; expenses it already generated keep their history
	// (DELETE /finance/rules/{id})
	DeleteExpenseRule(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update a recurring template — takes effect on the next generator pass, already-generated rows stay as they are
	// (PATCH /finance/rules/{id})
	UpdateExpenseRule(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// What is still owed to each advocate — collected, accrued at their percentage, paid out, remainder — plus the income split it is accrued on
	// (GET /finance/settlement)
	GetAdvocateSettlement(w http.ResponseWriter, r *http.Request, params GetAdvocateSettlementParams)
	// Queue an article for generation
	// (POST /generate)
	GenerateArticle(w http.ResponseWriter, r *http.Request)
	// Queue a batch from the next N unused sheet topics
	// (POST /generate/batch)
	GenerateBatch(w http.ResponseWriter, r *http.Request)
	// Health check
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// Aggregate lead/consultation stats over a date range, for the admin dashboard
	// (GET /leads/stats)
	GetLeadStats(w http.ResponseWriter, r *http.Request, params GetLeadStatsParams)
	// Place a backlink to one of our WordPress sites in each suitable donor's latest post
	// (POST /linkbuilding/place-backlinks)
	PlaceBacklinks(w http.ResponseWriter, r *http.Request)
	// Per-donor results of a placement run
	// (GET /linkbuilding/placements)
	ListPlacements(w http.ResponseWriter, r *http.Request, params ListPlacementsParams)
	// Successful placements across all runs (paginated, newest first)
	// (GET /linkbuilding/placements/history)
	ListPlacementHistory(w http.ResponseWriter, r *http.Request, params ListPlacementHistoryParams)
	// Request cancellation of a running placement
	// (POST /linkbuilding/placements/{run_id}/cancel)
	CancelPlacement(w http.ResponseWriter, r *http.Request, runId string)
	// The cases assigned to the advocate who is logged in — client contact, fee, what is paid, what is still owed, and the installments behind it
	// (GET /my/cases)
	ListMyCases(w http.ResponseWriter, r *http.Request)
	// Close an own case or put it back in progress; cancelling writes off what the client owes and stays an admin action
	// (PATCH /my/cases/{id}/status)
	SetMyCaseStatus(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Clients the advocate has a case with — a client who only ever had a consultation is not here, consultations carry no advocate
	// (GET /my/clients)
	ListMyClients(w http.ResponseWriter, r *http.Request)
	// One own client — name, phone, the advocate's own cases, the client's consultations and the note log; no address, birthdate or tax id, and no firm-wide revenue
	// (GET /my/clients/{id})
	GetMyClient(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Log a call or contact on an own client's card
	// (POST /my/clients/{id}/notes)
	AddMyClientNote(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// The advocate's own money — collected, their percentage, accrued, paid out, still owed, month by month; no colleague's row and no firm total
	// (GET /my/settlement)
	GetMySettlement(w http.ResponseWriter, r *http.Request)
	// Own scoreboard — cases by status, average fee, what clients still owe on own cases, collections by month
	// (GET /my/stats)
	GetMyStats(w http.ResponseWriter, r *http.Request)
	// List users
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// List saved password/credential entries
	// (GET /vault-entries)
	ListVaultEntries(w http.ResponseWriter, r *http.Request)
	// Add a password/credential entry
	// (POST /vault-entries)
	CreateVaultEntry(w http.ResponseWriter, r *http.Request)
	// Delete a password/credential entry
	// (DELETE /vault-entries/{id})
	DeleteVaultEntry(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update a password/credential entry
	// (PATCH /vault-entries/{id})
	UpdateVaultEntry(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// List WordPress sites
	// (GET /wordpress-sites)
	ListWordpressSites(w http.ResponseWriter, r *http.Request)
	// Add a WordPress site
	// (POST /wordpress-sites)
	CreateWordpressSite(w http.ResponseWriter, r *http.Request)
	// Soft-delete a WordPress site
	// (DELETE /wordpress-sites/{id})
	DeleteWordpressSite(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Get a WordPress site
	// (GET /wordpress-sites/{id})
	GetWordpressSite(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// Update a WordPress site
	// (PATCH /wordpress-sites/{id})
	UpdateWordpressSite(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
}

